// OnConflict allows configuring the `ON CONFLICT` / `ON DUPLICATE KEY` clause
// of the `INSERT` statement. For example:
//
//	client.ReturnRequest.CreateBulk(builders...).
//		OnConflict(
//			// Update the row with the new values
//			// the was proposed for insertion.
//			sql.ResolveWithNewValues(),
//		).
//		// Override some of the fields with custom
//		// update values.
//		Update(func(u *ent.ReturnRequestUpsert) {
//			SetCreatedAt(v+v).
//		}).
//		Exec(ctx)
func (_c *ReturnRequestCreateBulk) OnConflict(opts ...sql.ConflictOption) *ReturnRequestUpsertBulk {
	_c.conflict = opts
	return &ReturnRequestUpsertBulk{
		create: _c,
	}
}

// OnConflictColumns calls `OnConflict` and configures the columns
// as conflict target. Using this option is equivalent to using:
//
//	client.ReturnRequest.Create().
//		OnConflict(sql.ConflictColumns(columns...)).
//		Exec(ctx)
func (_c *ReturnRequestCreateBulk) OnConflictColumns(columns ...string) *ReturnRequestUpsertBulk {
	_c.conflict = append(_c.conflict, sql.ConflictColumns(columns...))
	return &ReturnRequestUpsertBulk{
		create: _c,
	}
}

// ReturnRequestUpsertBulk is the builder for "upsert"-ing
// a bulk of ReturnRequest nodes.
type ReturnRequestUpsertBulk struct {
	create *ReturnRequestCreateBulk
}

// UpdateNewValues updates the mutable fields using the new values that
// were set on create. Using this option is equivalent to using:
//
//	client.ReturnRequest.Create().
//		OnConflict(
//			sql.ResolveWithNewValues(),
//			sql.ResolveWith(func(u *sql.UpdateSet) {
//				u.SetIgnore(returnrequest.FieldID)
//			}),
//		).
//		Exec(ctx)
func (u *ReturnRequestUpsertBulk) UpdateNewValues() *ReturnRequestUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWithNewValues())
	u.create.conflict = append(u.create.conflict, sql.ResolveWith(func(s *sql.UpdateSet) {
		for _, b := range u.create.builders {
			if _, exists := b.mutation.ID(); exists {
				s.SetIgnore(returnrequest.FieldID)
			}
			if _, exists := b.mutation.CreatedAt(); exists {
				s.SetIgnore(returnrequest.FieldCreatedAt)
			}
			if _, exists := b.mutation.OrderGroupID(); exists {
				s.SetIgnore(returnrequest.FieldOrderGroupID)
			}
			if _, exists := b.mutation.StoreID(); exists {
				s.SetIgnore(returnrequest.FieldStoreID)
			}
			if _, exists := b.mutation.BuyerAccountID(); exists {
				s.SetIgnore(returnrequest.FieldBuyerAccountID)
			}
			if _, exists := b.mutation.Reason(); exists {
				s.SetIgnore(returnrequest.FieldReason)
			}
			if _, exists := b.mutation.RefundAmountMinor(); exists {
				s.SetIgnore(returnrequest.FieldRefundAmountMinor)
			}
			if _, exists := b.mutation.Currency(); exists {
				s.SetIgnore(returnrequest.FieldCurrency)
			}
			if _, exists := b.mutation.Lines(); exists {
				s.SetIgnore(returnrequest.FieldLines)
			}
		}
	}))
	return u
}

// Ignore sets each column to itself in case of conflict.
// Using this option is equivalent to using:
//
//	client.ReturnRequest.Create().
//		OnConflict(sql.ResolveWithIgnore()).
//		Exec(ctx)
func (u *ReturnRequestUpsertBulk) Ignore() *ReturnRequestUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWithIgnore())
	return u
}

// DoNothing configures the conflict_action to `DO NOTHING`.
// Supported only by SQLite and PostgreSQL.
func (u *ReturnRequestUpsertBulk) DoNothing() *ReturnRequestUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.DoNothing())
	return u
}

// Update allows overriding fields `UPDATE` values. See the ReturnRequestCreateBulk.OnConflict
// documentation for more info.
func (u *ReturnRequestUpsertBulk) Update(set func(*ReturnRequestUpsert)) *ReturnRequestUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWith(func(update *sql.UpdateSet) {
		set(&ReturnRequestUpsert{UpdateSet: update})
	}))
	return u
}

